public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("The number of triangles must be non-negative.");
    }
    // When N triangles are added, each new triangle can intersect with all previous ones
    // creating 2 new regions for each intersection plus 2 more regions.
    // So, the number of regions formed by N triangles is given by the formula:
    // R(N) = 2 + 2 * N + N * (N - 1)
    // Simplifying the formula, we get:
    // R(N) = N * N + N + 2
    return N * N + N + 2;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    // The formula to find the maximum number of regions is given by:
    // R(N) = N^2 + N + 2
    return N * N + N + 2;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("The number of triangles cannot be negative.");
    }
    if (N == 0) {
        return 1;
    }
    return (N * (N + 1) / 2) + 1;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    // Base case: no triangles, 1 region (the whole plane)
    if (N == 0) {
        return 1;
    }
    // Each new triangle can intersect with all previous triangles, adding 2 regions per intersection plus the new region inside the triangle
    // This results in the formula: maxRegions(N) = maxRegions(N-1) + 2*(N-1) + 1
    // Simplifying, we get: maxRegions(N) = N*(N+1) + 1
    return N * (N + 1) + 1;
}

