public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];

    // Convert paths to adjacency matrix for easier traversal
    boolean[][] adjMatrix = new boolean[n][n];
    for (int[] path : paths) {
        if (path.length != 2 || path[0] < 0 || path[0] >= n || path[1] < 0 || path[1] >= n) {
            continue; // Skip invalid paths
        }
        adjMatrix[path[0]][path[1]] = true;
        adjMatrix[path[1]][path[0]] = true; // Assuming undirected paths
    }

    if (!dfs(start[0], start[1], end[0], end[1], adjMatrix, visited)) {
        return "cannot be travelled";
    }

    return "can be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    if (start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || 
        end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Create a set to store the paths as edges
    Set<String> edgeSet = new HashSet<>();
    for (int[] path : paths) {
        if (path.length != 4) {
            return "cannot be travelled";
        }
        int x1 = path[0], y1 = path[1], x2 = path[2], y2 = path[3];
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
            return "cannot be travelled";
        }
        edgeSet.add(x1 + "," + y1 + "->" + x2 + "," + y2);
        edgeSet.add(x2 + "," + y2 + "->" + x1 + "," + y1);
    }

    // BFS to check if we can reach from start to end
    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited[start[0]][start[1]] = true;

    int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        for (int[] dir : directions) {
            int newX = current[0] + dir[0];
            int newY = current[1] + dir[1];
            if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY]) {
                String edge = current[0] + "," + current[1] + "->" + newX + "," + newY;
                if (edgeSet.contains(edge)) {
                    queue.offer(new int[]{newX, newY});
                    visited[newX][newY] = true;
                }
            }
        }
    }

    return "cannot be travelled";
}

