        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    if (start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    // Create a graph representation for the n-teresting space
    boolean[][] graph = new boolean[n][n];
    for (int[] path : paths) {
        if (path.length != 2 || path[0] < 0 || path[0] >= n || path[1] < 0 || path[1] >= n) {
            return "cannot be travelled";
        }
        graph[path[0]][path[1]] = true;
        graph[path[1]][path[0]] = true;
    }

    // Use BFS to check if there is a path from start to end
    boolean[][] visited = new boolean[n][n];
    visited[start[0]][start[1]] = true;
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        for (int[] direction : directions) {
            int newX = current[0] + direction[0];
            int newY = current[1] + direction[1];
            if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY] && graph[current[0]][current[1]] && graph[newX][newY]) {
                visited[newX][newY] = true;
                queue.add(new int[]{newX, newY});
            }
        }
    }

    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        return "Invalid input";
    }

    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    int[] count1 = new int[26];
    int[] count2 = new int[26];

    for (char c : word1.toCharArray()) {
        count1[c - 'A']++;
    }

    for (char c : word2.toCharArray()) {
        count2[c - 'A']++;
    }

    int common = 0;
    for (int i = 0; i < 26; i++) {
        common += Math.min(count1[i], count2[i]);
    }

    int totalLength = word1.length() + word2.length();

    if (totalLength == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = gcd(common, totalLength);
    common /= gcd;
    totalLength /= gcd;

    return "appx(" + word1 + ", " + word2 + ") = " + (common == 0 ? "0" : (common == totalLength ? "1" : common + "/" + totalLength));
}

