                }
            }
        }
    }

    for (int j = 1; j <= n / 2; j++) {
        if (totalSum * j % n == 0 && dp[n][j][totalSum * j / n]) {
            return true;
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length < 2) {
        throw new IllegalArgumentException("Cost array must contain at least two elements.");
    }

    int[] dp = new int[cost.length + 1];
    dp[0] = 0;
    dp[1] = 0;

    for (int i = 2; i <= cost.length; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[cost.length];
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("Cost array cannot be null or empty");
    }

    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }

    int first = cost[0];
    int second = cost[1];
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(first, second);
        first = second;
        second = current;
    }

    return Math.min(first, second);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }

    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < cost.length; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
