public boolean hasAllCodes(String s, int k) {
    if (k > s.length()) {
        return false;
    }

    int totalPossibleSubstrings = 1 << k; // 2^k
    boolean[] found = new boolean[totalPossibleSubstrings];
    int currentNumber = 0;

    for (int i = 0; i < s.length(); i++) {
        currentNumber = (currentNumber << 1) & (totalPossibleSubstrings - 1) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            found[currentNumber] = true;
        }
    }

    for (boolean f : found) {
        if (!f) {
            return false;
        }
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k < 0 || s.length() < (1 << k)) {
        return false;
    }

    Set<String> seen = new HashSet<>();
    int total = 1 << k; // Total number of binary strings of length k

    for (int i = 0; i <= s.length() - k; i++) {
        String substr = s.substring(i, i + k);
        seen.add(substr);
        if (seen.size() == total) {
            return true;
        }
    }

    return seen.size() == total;
}

