    int total = 1 << k; // Total number of binary strings of length k
    boolean[] found = new boolean[total];

    for (int i = 0; i <= s.length() - k; i++) {
        int num = 0;
        for (int j = i; j < i + k; j++) {
            num = (num << 1) | (s.charAt(j) - '0');
        }
        found[num] = true;
    }

    for (boolean exist : found) {
        if (!exist) {
            return false;
        }
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() == 0 || k <= 0) {
        return false;
    }

    int total = 1 << k; // Total number of binary strings of length k
    boolean[] found = new boolean[total];

    int value = 0;
    int mask = total - 1; // Mask to keep the last k bits

    for (int i = 0; i < s.length(); i++) {
        value = (value << 1) & mask; // Shift left and apply mask to keep k bits
        value += s.charAt(i) - '0'; // Add the current bit

        if (i >= k - 1 && !found[value]) { // Only consider valid substrings of length k
            found[value] = true;
            total--;
            if (total == 0) {
                return true;
            }
        }
    }

    return false;
}

