public int minInsertions(String s) {
    int open = 0; // Number of unmatched '('
    int insertions = 0; // Number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            open++;
        } else { // When we encounter a ')'
            if (open > 0) {
                open--; // Match it with an unmatched '('
            } else {
                insertions++; // Need to insert a '(' to match this ')'
            }
            // Check for two consecutive ')'
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next ')'
            } else {
                insertions++; // Need to insert another ')' to make it valid
            }
        }
    }

    // Add insertions for any remaining unmatched '('
    insertions += open * 2;

    return insertions;
}

public int minInsertions(String s) {
    int leftBalance = 0; // Number of unmatched '('
    int rightNeeded = 0; // Number of ')' needed to balance

    for (char c : s.toCharArray()) {
        if (c == '(') {
            leftBalance++;
        } else {
            if (leftBalance > 0) {
                leftBalance--; // Match with an existing '('
            } else {
                rightNeeded++; // Need to insert a '(' to match this ')'
            }
        }
    }

    // After processing, leftBalance represents the number of unmatched '('
    // Each unmatched '(' needs a ')' to balance, and each unmatched ')' needs a '('
    return leftBalance + rightNeeded;
}

