                right--;
            }
            // Increment the number of '(' that need to be matched
            left++;
        } else {
            // We found a ')'
            // Decrement the number of '(' that need to be matched
            left--;
            // If no '(' is left to match this ')', we need to add a '('
            if (left < 0) {
                // We need one '(' to balance this ')'
                left++;
                // This ')' is not balanced, so we need to add one ')'
                right++;
            }
        }
    }

    // The total number of insertions needed is the sum of unmatched '(' and needed ')'
    return left + right;
}

