public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int remainingValue = k - n; // Start by assuming all characters are 'a' (value 1)
    int remainingLength = n;

    while (remainingLength > 0) {
        if (remainingValue >= 25) { // Can we place a 'z'?
            result.append('z');
            remainingValue -= 25; // 'z' has a value of 26, so we subtract 25 from remainingValue
        } else { // Place the character that completes the required value
            result.append((char) ('a' + remainingValue));
            remainingValue = 0;
        }
        remainingLength--;
    }

    return result.reverse().toString(); // The result was built in reverse order, so reverse it
}

